{% import 'lua/helpers.lua' as h %}
WITH data(day, visits) AS (VALUES {{ h.sample_values(args.days) }})
SELECT day, visits,
       {% lua %}
         -- weekend flag computed by SQLite, written by Lua
         return "strftime('%w', day) IN ('0', '6')"
       {% endlua %} AS weekend
FROM data
WHERE {{ h.recent('day') }}
